 private void run(String mode,JsonNode expected,ObjectMapper json)throws Exception{Path file=Files.createTempFile("weknora-kb-write-parity-",".db");try{var source=new SQLiteDataSource();source.setUrl("jdbc:sqlite:"+file);try(var connection=source.getConnection()){ScriptUtils.executeSqlScript(connection,new FileSystemResource("../migrations/sqlite/000000_init.up.sql"));}var jdbc=new JdbcTemplate(source);String role="viewer",creator="caller";long owner=7;boolean enabled=true,cross=false,system=false,machine=mode.startsWith("api-key");boolean full=mode.equals("api-key-full");Set<String> caps=Set.of("ingest"),ids=Set.of();String method="POST",template="/api/v1/knowledge-bases/:id/knowledge/file",raw="/api/v1/knowledge-bases/kb/knowledge/file";
 switch(mode){case "viewer-other","system-admin-viewer","rbac-off-own"->creator="other";case "contributor-other"->{role="contributor";creator="other";}case "contributor-creator"->role="contributor";case "admin-other","missing-admin","lookup-failure-admin"->{role="admin";creator="other";}case "owner-blank"->{role="owner";creator="";}case "viewer-blank"->creator="";}
 system=mode.equals("system-admin-viewer");cross=mode.equals("cross-superuser-own")||mode.equals("cross-superuser-foreign");enabled=!Set.of("rbac-off-own","rbac-off-foreign","rbac-off-tenant-viewer").contains(mode);if(machine)creator="other";if(mode.equals("api-key-retrieval"))caps=Set.of("retrieval");if(mode.equals("api-key-scope"))ids=Set.of("other");if(mode.equals("api-key-update")){caps=Set.of("manage_kbs");method="PUT";template="/api/v1/knowledge-bases/:id";raw="/api/v1/knowledge-bases/kb";}
 boolean shared=false;if(Set.of("foreign-no-share","cross-superuser-foreign","rbac-off-foreign").contains(mode)){owner=8;role="contributor";}else if(mode.startsWith("share-")||Set.of("member-viewer","tenant-viewer","rbac-off-tenant-viewer","source-gone","target-gone","org-deleted","multiple-shares","empty-share-permission","empty-member-role","api-key-shared-editor").contains(mode)){owner=8;shared=true;role="contributor";}if(mode.equals("tenant-viewer")||mode.equals("rbac-off-tenant-viewer"))role="viewer";
 if(shared){String permission=mode.equals("share-admin")?"admin":mode.equals("share-viewer")?"viewer":mode.equals("empty-share-permission")?"":"editor";String member=mode.equals("share-admin")?"admin":mode.equals("member-viewer")?"viewer":mode.equals("empty-member-role")?"":"editor";long sourceTenant=mode.equals("share-foreign-source-member")?9:8;jdbc.update("INSERT INTO organizations(id,name,owner_tenant_id,owner_id) VALUES('org','Org',8,'unused')");jdbc.update("INSERT INTO organization_tenant_members(id,organization_id,tenant_id,role) VALUES('source','org',?,'admin'),('target','org',7,?)",sourceTenant,member);jdbc.update("INSERT INTO kb_shares(id,knowledge_base_id,organization_id,source_tenant_id,permission,shared_by_user_id) VALUES('share','kb','org',?,?,'unused')",sourceTenant,permission);
 if(mode.equals("source-gone"))jdbc.update("DELETE FROM organization_tenant_members WHERE id='source'");if(mode.equals("target-gone"))jdbc.update("DELETE FROM organization_tenant_members WHERE id='target'");if(mode.equals("org-deleted"))jdbc.update("UPDATE organizations SET deleted_at=CURRENT_TIMESTAMP WHERE id='org'");if(mode.equals("share-deleted"))jdbc.update("UPDATE kb_shares SET deleted_at=CURRENT_TIMESTAMP WHERE id='share'");if(mode.equals("multiple-shares")){jdbc.update("UPDATE kb_shares SET permission='viewer'");jdbc.update("INSERT INTO organizations(id,name,owner_tenant_id,owner_id) VALUES('org2','Second',8,'unused')");jdbc.update("INSERT INTO organization_tenant_members(id,organization_id,tenant_id,role) VALUES('source2','org2',8,'viewer'),('target2','org2',7,'admin')");jdbc.update("INSERT INTO kb_shares(id,knowledge_base_id,organization_id,source_tenant_id,permission,shared_by_user_id) VALUES('share2','kb','org2',8,'editor','unused')");}if(mode.equals("share-sql-failure"))jdbc.execute("DROP TABLE kb_shares");}
 if(!mode.startsWith("missing-"))jdbc.update("INSERT INTO knowledge_bases(id,name,tenant_id,creator_id,type,embedding_model_id,summary_model_id) VALUES('kb','KB',?,?,'document','','')",owner,creator);
 if(mode.startsWith("lookup-failure-"))jdbc.execute("DROP TABLE knowledge_bases");var audit=new DeniedRoleAuditService(jdbc,new AuthRepository(jdbc,json),new DataSourceTransactionManager(source));var writes=new KnowledgeBaseWriteAuthorization(jdbc,new com.tencent.weknora.knowledge.KnowledgeBaseCodec(json),audit);var auth=new AuthContext("caller",7,role,system,machine?1L:null,full,caps,ids,cross,enabled);int status=200;Object body;
 try{var grant=method.equals("PUT")?writes.authorizeUpdate(auth,"kb",raw,method):writes.authorizeUpload(auth,"kb",raw,method);body=Map.of("effective_tenant_id",grant.effectiveTenantId(),"permission",grant.permission(),"own_tenant",grant.ownTenant(),"caller_tenant_id",auth.tenantId());}catch(ApiException ex){status=ex.status();body=ex.response();if(body==null){Map<String,Object> error=new LinkedHashMap<>();error.put("code",ex.appCode());error.put("message",ex.getMessage());error.put("details",ex.details());body=Map.of("success",false,"error",error);}}
 List<Map<String,Object>> rows=new ArrayList<>();for(var row:jdbc.queryForList("SELECT tenant_id,actor_user_id,actor_role,action,request_path,request_method,outcome,details FROM audit_logs ORDER BY id")){row.put("details",json.readTree(row.get("details").toString()));rows.add(row);}assertEquals(expected,json.readTree(json.writeValueAsBytes(Map.of("status",status,"body",body,"audits",rows))));
 }finally{Files.deleteIfExists(file);}}
